/* Account-scoped payment choices for simulated travel orders. */
(function(root){'use strict';
let choice=null;
const account=()=>String(actId()||'main'),store=()=>{const t=tvInit();return t.paymentRequests||(t.paymentRequests=[]);},name=c=>String(c?.remark||'').trim()||String(c?.name||'').trim()||'原付款方',clone=x=>JSON.parse(JSON.stringify(x)),money=x=>'¥'+Number(x).toFixed(2);
function roles(){return (S.contacts||[]).filter(c=>!c.deleted&&!c.blocked&&!c.isPhoneFriend);}
function familyLeft(c){const f=c.family;if(!f||!f.bound)return 0;return Math.max(0,Number(f.quota)-(f.month===curMonth()?Number(f.used)||0:0));}
function open(d){if(!d||!Number.isSafeInteger(Math.round(d.amount*100))||d.amount<0)return false;choice=clone({...d,account:account()});show();return true;}
function show(){if(!choice||choice.account!==account())return;const rs=roles(),fs=rs.filter(c=>c.family?.bound);openModal('<div class="cth-dialog ctp-dialog"><div class="ctp-brand">小鱼旅行 · 模拟预订</div><h3>选择付款方式</h3><div class="ctp-summary"><b>'+esc(choice.name)+'</b><span>'+esc(choice.detail||'')+'</span><strong>'+money(choice.amount)+'</strong></div><button onclick="NorthTravelPayment.pay(\'self\')">我的钱包付款</button><button class="ctp-secondary" onclick="NorthTravelPayment.select(\'role\')" '+(!rs.length?'disabled':'')+'>选择代付人</button><button class="ctp-secondary" onclick="NorthTravelPayment.select(\'family\')" '+(!fs.length?'disabled':'')+'>亲属卡付款</button><p>代付需等待对方同意；亲属卡按本月可用额度支付。</p><button class="cth-cancel" onclick="closeModal()">取消</button></div>');}
function select(mode){if(!choice||choice.account!==account())return false;const list=roles().filter(c=>mode!=='family'||c.family?.bound);if(!list.length)return false;openModal('<div class="cth-dialog ctp-dialog"><div class="ctp-brand">小鱼旅行 · '+(mode==='family'?'亲属卡':'代付')+'</div><h3>'+(mode==='family'?'选择亲属卡':'请谁帮忙代付')+'</h3><div class="ctp-summary"><b>'+esc(choice.name)+'</b><strong>'+money(choice.amount)+'</strong></div><label>'+(mode==='family'?'亲属卡持有人':'代付人')+'<select id="ctpPayer">'+list.map(c=>'<option value="'+esc(c.id)+'">'+esc(name(c))+(mode==='family'?' · 剩余额度 '+money(familyLeft(c)):'')+'</option>').join('')+'</select></label><button onclick="NorthTravelPayment.pay(\''+mode+'\',document.getElementById(\'ctpPayer\').value)">'+(mode==='family'?'确认亲属卡付款':'发送代付请求')+'</button><button class="cth-cancel" onclick="NorthTravelPayment.show()">返回</button></div>');return true;}
function dispatch(d,p){if(d.account!==account())return false;let o;if(d.kind==='hotel')o=NorthTravelHotel.bookNow(d.index,p,d.signature);else if(d.kind==='ticket')o=NorthTravelGuide.bookNow(d.item,p,d.signature);else {const api=d.kind==='flight'?NorthFlightBooking:d.kind==='train'?NorthTrainBooking:NorthConcertBooking;const before=api.rows().map(x=>x.id);if(api.bookQuote(clone(d.quote),d.item,null,p))o=api.rows().find(x=>!before.includes(x.id));}return o||false;}
function requestMessage(r,c,type){const m={id:uid(),time:Date.now(),role:type==='paid'?'assistant':'user',type,shop:'小鱼旅行',kind:'travel',name:r.name,price:r.amount,travelPayment:r.id,used:c?.family?.used,quota:c?.family?.quota};pushMsg(c.id,m);return m;}
function pay(mode,cid){const d=choice;if(!d||d.account!==account())return false;const c=cid&&roles().find(x=>x.id===cid);if(mode!=='self'&&!c)return false;const duplicate=store().find(r=>r.account===account()&&r.status==='pending'&&r.roleId===cid&&JSON.stringify(r.descriptor)===JSON.stringify(d));if(duplicate){toast('代付请求已发送，请等待角色回复');return false;}const r={id:uid(),account:account(),name:d.name,amount:d.amount,kind:d.kind,descriptor:clone(d),mode,roleId:cid||'',status:mode==='role'?'pending':'paying',ts:Date.now()};store().push(r);if(mode==='role'){requestMessage(r,c,'paycard');save();choice=null;closeModal();toast('已发送代付请求，尚未扣款或预订');scheduleReply(c.id);return true;}const o=dispatch(d,{mode,roleId:cid,amount:d.amount,requestId:r.id});if(!o){r.status='failed';save();return false;}r.status='paid';r.orderId=o.id;choice=null;if(mode==='family'){requestMessage(r,c,'familybuy');scheduleReply(c.id,'[系统：用户刚用你的亲属卡支付了小鱼旅行模拟订单「'+r.name+'」，'+money(r.amount)+'。订单确实已生成，亲属卡本月已用'+money(c.family.used)+'。]');}save();closeModal();receipt(r.id);return true;}
function currentRequest(cid){const m=[...msgs(cid)].reverse().find(x=>x.role==='user'&&x.type==='paycard');return m?.travelPayment&&store().find(r=>r.id===m.travelPayment&&r.account===account()&&r.roleId===cid)||null;}
function pending(cid){const m=[...msgs(cid)].reverse().find(x=>x.role==='user'&&x.type==='paycard'&&!x._paid&&!x._rejected);if(!m?.travelPayment)return null;return store().find(r=>r.id===m.travelPayment&&r.account===account()&&r.status==='pending'&&r.roleId===cid)||null;}
function accept(c,reject=false){const r=c&&pending(c.id);if(!r)return currentRequest(c.id)?.status==='paid';const m=msgs(c.id).find(x=>x.travelPayment===r.id&&x.type==='paycard');if(reject){r.status='rejected';if(m)m._rejected=true;save();return true;}const o=dispatch(r.descriptor,{mode:'role',roleId:c.id,amount:r.amount,requestId:r.id});if(!o){r.status='failed';if(m)m._rejected=true;save();toast('代付未完成，未生成新订单');return false;}r.status='paid';r.orderId=o.id;if(m)m._paid=true;requestMessage(r,c,'paid');save();return true;}
function roleDelta(c,source,cents,o,note){const spy=S.spy?.[c.id];const raw=source==='roleWallet'?c.wallet:source==='roleBank'&&spy?(spy.balance??(spy.wallet||[]).reduce((s,x)=>s+Number(x.amount||0),0)):null;if(raw===null)return false;const next=NorthHotelData.moneyNext(raw,cents);if(next===null)return false;if(source==='roleWallet')c.wallet=next;else spy.balance=next;if(spy){spy.wallet=spy.wallet||[];spy.wallet.unshift({item:note,amount:cents/100,when:o.date||o.checkIn||todayStr(),travelOrderId:o.id});}return true;}
function charge(p,cents,note,o){if(!p||!Number.isSafeInteger(cents)||cents<0||cents!==Math.round(p.amount*100))return false;const r=store().find(x=>x.id===p.requestId&&x.account===account()&&['pending','paying'].includes(x.status));if(!r)return false;if(p.mode==='self'){const n=NorthHotelData.moneyNext(S.me.balance,-cents);if(n===null){toast('模拟钱包余额不足');return false;}addBill('out',cents/100,note);o.fundingSource='userWallet';return true;}const c=roles().find(x=>x.id===p.roleId);if(!c)return false;if(p.mode==='family'){if(S.couple?.cardFrozen||!c.family?.bound||familyLeft(c)*100+0.01<cents){toast('亲属卡被冻结或本月额度不足');return false;}const f=c.family;if(f.month!==curMonth()){f.month=curMonth();f.used=0;}f.used=Number((Number(f.used||0)+cents/100).toFixed(2));o.fundingSource='familyCard';o.familyMonth=f.month;o.payer='family';}else if(p.mode==='role'){const m=tvHotelRoleMoney(c);if(!m||!roleDelta(c,m.source,-cents,o,note)){toast('角色自己的模拟银行余额不足');return false;}o.fundingSource=m.source;o.payer='ta';}else return false;o.paymentRequested=true;o.paymentRequestId=r.id;o.fundingRoleId=c.id;o.knownRoleIds=[...new Set([...(o.knownRoleIds||[]),c.id])];return true;}
function label(o){return NorthHotelData.payerLabel(o);}
function refund(o){if(!o?.paymentRequested||String(o.accountId||'main')!==account()||o.paymentRefunded)return false;const c=getC(o.fundingRoleId),cents=Math.round(Number(o.price??o.amount)*100);if(!c||c.deleted||!Number.isSafeInteger(cents)||cents<0)return false;if(o.fundingSource==='familyCard'){if(!c.family?.bound)return false;if(c.family.month===o.familyMonth)c.family.used=Math.max(0,Number((Number(c.family.used||0)-cents/100).toFixed(2)));}else if(!roleDelta(c,o.fundingSource,cents,o,'旅行订单原路退款'))return false;o.paymentRefunded=true;return true;}
function card(m){const r=store().find(x=>x.id===m.travelPayment&&x.account===account());if(!r)return '<div class="ctp-payment-card">付款记录不可用</div>';const c=getC(r.roleId),o=[...(tvInit().hotels||[]),...(tvInit().trips||[]),...(tvInit().ticketOrders||[]),...(tvInit().concertOrders||[])].find(o=>o.id===r.orderId),refunded=o&&['cancelled','refunded'].includes(o.status),title=refunded?'付款已原路退回':r.status==='paid'?(r.mode==='family'?name(c)+'的亲属卡已付款':r.mode==='role'?name(c)+'代付成功':'钱包付款成功'):r.status==='rejected'?name(c)+'未同意代付':r.status==='failed'?'付款未完成':'向'+name(c)+'请求代付 · 等待回复';return '<div class="ctp-payment-card" data-payment="'+esc(r.id)+'" onclick="event.stopPropagation();NorthTravelPayment.receipt(this.dataset.payment)"><div class="ctp-brand">小鱼旅行 · 模拟订单</div><div class="ctp-card-title">'+esc(title)+'</div><b>'+esc(r.name)+'</b><strong>'+money(r.amount)+'</strong><p>'+(r.mode==='family'?'亲属卡 · ':r.mode==='role'?'代付人 · ':'付款方式 · ')+esc(r.mode==='self'?'我的钱包':name(c))+'</p>'+(r.mode==='family'&&c?.family?'<p>本月已用 '+money(c.family.used)+' / '+money(c.family.quota)+'</p>':'')+'<div class="ctp-card-foot">'+(refunded?'订单已退订 · 原路退款':r.status==='paid'?'订单已生成 · 查看付款记录':'尚未扣款或预订')+'</div></div>';}
function receipt(id){const r=store().find(x=>x.id===id&&x.account===account());if(!r)return false;openModal('<div class="cth-dialog ctp-dialog"><h3>付款记录</h3>'+card({travelPayment:id})+'<button class="cth-cancel" onclick="closeModal()">完成</button></div>');return true;}
root.NorthTravelPayment={open,show,select,pay,pending,currentRequest,accept,charge,refund,label,card,receipt};
})(globalThis);
